// ISS-2025-00820
function getPayload( frm ) {
    let deleted = frm.deletedPositions;

    return {
        timesheet_name: frm.doc.name,
        positions: ( deleted 
            ? frm.ts_positions.filter(( pos ) => !deleted.some( ( del ) => del == pos.name ) )
            : frm.ts_positions )
    };
}

async function checkLimits(frm) {
    const warnings = [];

    if (!frm.ts_positions || !frm.doc.name) return warnings;

    const payload = getPayload( frm );

    let result = await frappe.call({
        method: 'project_workload_assignment.api.calculate_timesheet_limits',
        args: payload,
    });

    if (result?.message) {
        result.message.forEach(r => {
           if (r.status == "block" || r.status == "warning") {
                warnings.push(r);
            } 
        });
    }

    return warnings;
}

function refresh_limits(frm) {
    if (!frm.ts_positions || !frm.doc.name) return;

    const payload = getPayload( frm );

    frappe.call({
        method: 'project_workload_assignment.api.calculate_timesheet_limits',
        args: payload,
        callback: ({ message }) => {
            if ( message) {
                apply_limit_styles(frm, message);
            }
        }
    });
}

function apply_limit_styles(frm, results) {
    results.forEach(r => {
        const btn = $(`#limits-${r.position }`);
        if (btn.length) {
            setButtonStyle(btn, r.status);
            let tooltip = ( r.planned_hours > 0 
                ? `${r.completion_percentage}% из ${r.planned_hours} ч.`
                : __("Planned work efforts are not defined") );
            btn.attr('title', tooltip);
        }
    });
}

//функция для стилей кнопок
function setButtonStyle(button, status) {
    const styles = {
        'block': { // Красный - превышена блокировка
            'color': '#f44336'
        },
        'message': { // Оранжевый - превышено уведомление
            'color': '#FF9800'
        },
        'warning': { // Желтый - превышено предупреждение
            'color': '#FFEB3B'
        },
        'normal': { // Зеленый - все в порядке
            'color': '#4CAF50'
        },
        'no-plan': { // Серый - нет плановых данных
            'color': '#9E9E9E'
        }
    };

    button.css(styles[status] || styles['no-data']);
}

// Функция для проверки плановых трудозатрат согласно настройки проекта ISS-2025-01298
function checkPlannedHoursAndLimits(frm) {
    return new Promise(async (resolve) => {
        const errors = [];
        const warnings = [];

        try {
            const positions = frm.ts_positions || [];

            if (!positions.length || !frm.doc.name) {
                return resolve({ errors, warnings });
            }

            // Упрощенный вызов - передаем только необходимые данные
            const planCheck = await frappe.call({
                method: 'project_workload_assignment.api.calculate_timesheet_limits',
                args: {
                    timesheet_name: frm.doc.name,
                    positions: positions.map(p => ({
                        name: p.name,
                        document_name: p.document_name,
                        project_role: p.project_role,
                        project: p.project,
                        status: p.status,
                        all_hours: p.all_hours
                        // Убрали передачу plan_required - теперь определяется на сервере
                    }))
                }
            });

            // Обработка результатов остается прежней
            (planCheck.message || []).forEach(r => {
                if (r.status === "block") {
                    if (r.planned_hours > 0) {
                        const max_hrs = r.limit * r.planned_hours / 100;
                        errors.push(
                            `Трудозатраты по задаче "${r.task_subject}" (роль: ${r.role}) ` +
                            `превысили блокирующий лимит (${max_hrs} ч.) ` +
                            `на ${r.total_hours - max_hrs} часа(ов).`
                        );
                    } else {
                        errors.push(
                            `Для задачи "${r.task_subject}" (роль: ${r.role}) ` +
                            `не определены обязательные плановые трудозатраты`
                        );
                    }
                } else if (r.status === "warning") {
                    warnings.push(r);
                }
            });
        } catch (error) {
            console.error('Error in checkPlannedHoursAndLimits:', error);
            errors.push('Ошибка при проверке плановых трудозатрат и лимитов');
        }

        resolve({ errors, warnings });
    });
}

function showTaskPlanFact(position, frm, buttonElement) {
    if (!position.document_name || position.document_name.trim() === '') {
        frappe.msgprint('Не выбрана задача для отображения информации');
        return;
    }

    let modal;
    const payload = getPayload(frm);

    frappe.call({
        method: 'project_workload_assignment.api.calculate_timesheet_limits',
        args: payload,
    }).then(results => {
        let result = results?.message.find((element) => element.position == position.name);

        modal = $(`
            <div class="modal fade" tabindex="-1" role="dialog" style="display: none;">
                <div class="modal-dialog" role="document" style="max-width: 650px;">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">${result.task_subject || position.document_name}</h5>
                            <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                                <span aria-hidden="true">&times;</span>
                            </button>
                        </div>
                        <div class="modal-body">
                            ${result.planned_hours <= 0 && result.plan_required ? getNoPlanWarningHtml() : ''}
                            ${getCompletionTableHtml(result)}
                            ${getHoursNoteHtml(result)}
                            ${getCurrentUserHoursHtml(result, frm)}
                            ${getHoursUsers(result)}
                            ${getParentTaskInfoHtml(result)}
                        </div>
                        <div class="modal-footer">
                            <button type="button" class="btn btn-default btn-sm" data-dismiss="modal">Закрыть</button>
                        </div>
                    </div>
                </div>
            </div>
        `).appendTo('body');

        modal.on('click', 'a[data-task-link]', function(e) {
            e.preventDefault();
            const taskName = $(this).data('taskName');
            modal.modal('hide');
            frappe.set_route('Form', 'Task', taskName);
        });

        modal.modal('show');

        modal.on('hidden.bs.modal', function() {
            modal.remove();
        });
    });
}

function getNoPlanWarningHtml() {
    return `
        <div class="alert alert-danger" style="margin-bottom: 15px;">
            <i class="fa fa-exclamation-triangle"></i>
            <strong> Внимание!</strong> Для этой задачи обязательно указание плановых трудозатрат!
        </div>
    `;
}

function getCompletionTableHtml(result) {
    const calculatePercentage = (value) => {
        return result.planned_hours > 0 ? Math.round((value / result.planned_hours) * 100) : 0;
    };

    let rows = [];
    for (var key in result.hours_data) {
        if ( key != "users" && key != "user_hours" ) {
            rows.push({
                status: key == "total" ? __("Total") : key,
                isTotal: key == "total",
                plan: Number.parseFloat( result.planned_hours).toFixed( 1 ) ,
                fact: Number.parseFloat( result.hours_data[ key ] ).toFixed( 1 ) + ' ч.',
                percent: calculatePercentage( result.hours_data[ key ] )
            });
        }
    }

    return `
        <div class="frappe-table-container" style="margin-bottom: 15px;">
            <table class="table table-bordered" style="width: 100%; margin-bottom: 10px;">
                <thead>
                    <tr>
                        <th style="width: 30%;">Статус</th>
                        <th style="width: 20%; text-align: right;">План</th>
                        <th style="width: 20%; text-align: right;">Факт</th>
                        <th style="width: 30%;">% выполнения</th>
                    </tr>
                </thead>
                <tbody>
                    ${rows.map(row => `
                        <tr ${row.isTotal ? 'style="font-weight: bold;"' : ''}>
                            <td>${row.status}</td>
                            <td style="text-align: right;">${row.plan}</td>
                            <td style="text-align: right;">${row.fact}</td>
                            <td>
                                <div class="progress" style="height: 20px; margin-bottom: 0; ${row.percent > 100 ? 'position: relative;' : ''}">
                                    <div class="progress-bar ${row.percent > 100 ? 'progress-bar-danger' : 'progress-bar-success'}" 
                                         role="progressbar" 
                                         style="width: ${Math.min(row.percent, 100)}%;">
                                        ${row.percent <= 100 ? row.percent + '%' : ''}
                                    </div>
                                    ${row.percent > 100 ? 
                                        `<div class="progress-bar progress-bar-danger" 
                                              role="progressbar"
                                              style="width: ${row.percent - 100}%;">
                                         </div>
                                         <div style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-weight: bold; color: white;">
                                            ${row.percent}%
                                         </div>` : ''}
                                </div>
                            </td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        </div>
    `;
}

function getCurrentUserHoursHtml(result, frm) {
    const ownerFullName = frm.doc.timesheet_from_name;
    if (!ownerFullName) return '';

    const userHours = result.hours_data.user_hours || {};
    const ownerHoursByStatus = userHours[ownerFullName] || {};

    let totalOwnerHours = 0;
    for (const status in ownerHoursByStatus) {
        if (!Object.prototype.hasOwnProperty.call(ownerHoursByStatus, status)) continue;
        if (typeof ownerHoursByStatus[status] !== 'number') continue;
        totalOwnerHours += ownerHoursByStatus[status];
    }
    if (totalOwnerHours === 0) return '';

    const percentage = result.planned_hours > 0
        ? Math.round((totalOwnerHours / result.planned_hours) * 100)
        : 0;

    let statusBreakdown = '';
    const statuses = Object.keys(ownerHoursByStatus);
    if (statuses.length > 1) {
        statusBreakdown = `<br><small style="color: #6c757d;">`;
        statusBreakdown += statuses.map(status =>
            `${status}: ${ownerHoursByStatus[status].toFixed(2)} ч.`
        ).join(' | ');
        statusBreakdown += `</small>`;
    } else if (statuses.length === 1) {
        statusBreakdown = `<br><small style="color: #6c757d;">Статус: ${statuses[0]}</small>`;
    }

    return `
        <div style="margin: 15px 0; padding: 8px 10px; background-color: #f0f7ff; border-radius: 4px; border-left: 4px solid #007bff;">
            <strong>👤 ${ownerFullName}:</strong>
            <span style="font-size: 16px; font-weight: bold; color: #007bff;">${totalOwnerHours.toFixed(2)} ч.</span>
            ${result.planned_hours > 0 ? `
                <span style="color: #6c757d;"> (${percentage}% от плана)</span>
            ` : ''}
            ${statusBreakdown}
        </div>
    `;
}

function getHoursUsers(result) {
    let users = result.hours_data.users || [];
    users.push( cur_frm.doc.timesheet_from_name );
    users = [...new Set( users )].filter(( user ) => user && user != "" );
    if ( users ) {
        return `<br>Учтены часы от: ` + frappe.utils.comma_and( users );
    }
}

function getHoursNoteHtml(result) {
    if (result.used_children_for_actual ) {
        return `Фактические данные: с учетом других дочерних задач (${result.child_tasks_count} шт.)`;
    } else {
        return `Фактические данные: только текущая задача`;
    }
}

function getParentTaskInfoHtml(result) {
    if (result.planned_hours > 0) {
        let html = `
            <div class="hours-note">
                Плановые данные определены на уровне: ${result.plan_task_subject}
            </div>`;

        if (result.plan_sources && result.plan_sources.length > 0) {
            html += `<div class="hours-note">
                Источники плана:
                <ul>`;
            result.plan_sources.forEach(source => {
                html += `<li>${source.subject} (${source.task_name}): ${source.planned_hours} ч.</li>`;
            });
            html += `</ul></div>`;
        }

        return html;
    }
    return "";
}

async function refresh_list_limits(positions) {
    frappe.call({
        method: 'project_workload_assignment.api.calculate_timesheet_limits',
        args: {
            timesheet_name: "",
            positions: positions
        },
        callback: ({ message }) => {
            if ( message) {
                apply_list_limit_styles(message);
            }
        }
    });
}

function apply_list_limit_styles(results) {
    //async function updatePlanFactButtonStyle(button, doc, limitsMap) {
    try {
        // Получаем данные через серверный метод
        //const hoursData = await getHoursData(doc);
        results.forEach(hoursData => {
            const button = $(`button.plan-fact-button[data-docname='${hoursData.position }'`);
            // Устанавливаем стиль кнопки на основе статуса
            setListButtonStyle(button, hoursData.status);

            // Формируем подсказку
            let tooltip = hoursData.planned_hours > 0 
                ? `${hoursData.completion_percentage.toFixed( 1 )}% из ${hoursData.planned_hours.toFixed( 1 )} ч.`
                : __("Planned work efforts are not defined");

            button.attr('title', tooltip);
        });
    } catch (error) {
        console.error('Error updating button style:', error);
        setListButtonStyle(button, 'no-plan');
    }
}

function setListButtonStyle(button, status) {
    const styles = {
        'block': { // Красный - превышена блокировка
            'color': '#f44336'
        },
        'message': { // Оранжевый - превышено уведомление
            'color': '#FF9800'
        },
        'warning': { // Желтый - превышено предупреждение
            'color': '#FFEB3B'
        },
        'normal': { // Зеленый - все в порядке
            'color': '#4CAF50'
        },
        'no-plan': { // Серый - нет плановых данных
            'color': '#9E9E9E'
        }
    };

    button.css(styles[status] || styles['no-data']);
}

// Обновленная функция для получения данных план-факт
async function getHoursData(position) {
    try {
        // Используем серверный метод для получения данных
        const result = await frappe.call({
            method: 'project_workload_assignment.api.calculate_timesheet_limits',
            args: {
                timesheet_name: '', // Пустое значение, так как мы работаем с отдельными позициями
                positions: [position]
            },
            freeze: false
        });

        if (result && result.message && result.message.length > 0) {
            const data = result.message[0];

            return {
                totalHours: data.total_hours || 0,
                editingHours: data.hours_data?.Редактирование || 0,
                approvalHours: data.hours_data?.['На согласовании'] || 0,
                approvedHours: data.hours_data?.Согласовано || 0,
                rejectedHours: data.hours_data?.Отклонено || 0,
                plannedHours: data.planned_hours || 0,
                completionPercentage: data.completion_percentage || 0,
                usedChildrenForActual: data.used_children_for_actual || false,
                usedParentForPlan: data.used_parent_for_plan || false,
                parentTaskName: data.parentTaskName || '',
                parentTaskSubject: data.parentTaskSubject || '',
                taskSubject: data.task_subject || position.document_name,
                childTasksCount: data.child_tasks_count || 0,
                hasOwnHours: data.hasOwnHours || false,
                status: data.status || 'no-plan',
                limit: data.limit,
                // Добавляем недостающие поля:
                plan_required: data.plan_required || false,
                plan_task_subject: data.plan_task_subject || ''
            };
        }

        return getDefaultHoursData(position);
    } catch (error) {
        console.error('Error getting hours data:', error);
        return getDefaultHoursData(position);
    }
}

// Функция для получения данных по умолчанию
function getDefaultHoursData(position) {
    return {
        totalHours: 0,
        editingHours: 0,
        approvalHours: 0,
        approvedHours: 0,
        rejectedHours: 0,
        plannedHours: 0,
        completionPercentage: 0,
        usedChildrenForActual: false,
        usedParentForPlan: false,
        parentTaskName: '',
        parentTaskSubject: '',
        taskSubject: position.document_name || '',
        childTasksCount: 0,
        hasOwnHours: false,
        status: 'no-plan',
        // Добавляем недостающие поля:
        plan_required: false,
        plan_task_subject: ''
    };
}

frappe.ui.form.on("Project", {
	refresh(frm) {
		apply_worker_team_ui(frm);
	},
	custom_ts_details_add(frm) {
		apply_worker_team_ui(frm);
	}
});

frappe.ui.form.on("Project Team Details", {
	pt_worker(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (!row.pt_worker) {
			return;
		}
		frappe.db.get_value("Worker", row.pt_worker, ["wuser", "wtype"]).then((r) => {
			if (!r.message) {
				return;
			}
			if (r.message.wuser) {
				frappe.model.set_value(cdt, cdn, "pt_participant_type", "User");
				frappe.model.set_value(cdt, cdn, "pt_participant", r.message.wuser);
			}
			if (r.message.wtype) {
				frappe.model.set_value(cdt, cdn, "worker_type", r.message.wtype);
			}
		});
	},
	virtual_worker(frm, cdt, cdn) {
		if (!frappe.meta.get_docfield("Project Team Details", "virtual_worker")) {
			return;
		}
		const row = locals[cdt][cdn];
		if (row.virtual_worker) {
			frappe.model.set_value(cdt, cdn, "pt_worker", null);
			frappe.model.set_value(cdt, cdn, "pt_participant_type", null);
			frappe.model.set_value(cdt, cdn, "pt_participant", null);
		}
		apply_worker_team_ui(frm);
	}
});

function apply_worker_team_ui(frm) {
	const grid = frm.fields_dict.custom_ts_details && frm.fields_dict.custom_ts_details.grid;
	if (!grid) {
		return;
	}
	if (!frappe.meta.get_docfield("Project Team Details", "pt_worker")) {
		return;
	}
	// Worker is the primary control when timesheets is installed.
	grid.update_docfield_property("pt_worker", "hidden", 0);
	grid.update_docfield_property("pt_worker", "in_list_view", 1);
	grid.update_docfield_property("pt_participant", "hidden", 1);
	grid.update_docfield_property("pt_participant_type", "hidden", 1);
	frm.refresh_field("custom_ts_details");
}

// Глобальное переопределение frappe.msgprint для отлова пустых сообщений
const originalMsgprint = frappe.msgprint;
//var originalMsgprint = frappe.msgprint;

frappe.msgprint = function(message, opts) {
    console.trace('frappe.msgprint called with:', message, opts);

    // Обработка массива сообщений
    if (Array.isArray(message)) {
        const filteredMessages = message.filter(msg => {
            if (typeof msg === 'string') {
                try {
                    const parsed = JSON.parse(msg);
                    return parsed.message && parsed.message.trim() !== "";
                } catch {
                    return msg.trim() !== "";
                }
            }
            return true; // оставляем нестроковые элементы
        });

        if (filteredMessages.length === 0) {
            console.warn("Все сообщения пустые - игнорируем");
            return;
        }
        
        return originalMsgprint(filteredMessages, opts);
    }

    // Обработка строки
    if (typeof message === 'string' && message.trim() === "") {
        console.warn("Пустая строка - игнорируем");
        return;
    }

    // Обработка объектов
    if (message && typeof message === 'object' && message.message && message.message.trim() === "") {
        console.warn("Пустое сообщение в объекте - игнорируем");
        return;
    }

    // Во всех остальных случаях вызываем оригинальный метод
    return originalMsgprint.apply(this, arguments);
};

frappe.ui.form.on('Application For Leave', {
    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action === 'Не согласовано') {
            return requireRejectionComment(frm);
        }
        return true;
    },

    refresh: function(frm) {
        showDashboard(frm);
        checkTransitions(frm);
    },
    
    alto_date: function(frm) {
        let doc = frm.doc;
        if (doc.alfrom_date && doc.alto_date && 
            frappe.datetime.get_day_diff(doc.alfrom_date, doc.alto_date) > 0) {
            frappe.show_alert({
                message: __('Дата окончания не может быть раньше даты начала!'),
                indicator: 'orange'
            }, 5);
            frm.set_value("alto_date", doc.alfrom_date);
        }
    }
});

// Основная функция для обработки комментария при отклонении
function requireRejectionComment(frm) {
    return new Promise((resolve) => {
        setTimeout(() => {
            const dialog = frappe.prompt({
                fieldtype: 'Text',
                label: ('Причина Отклонения'),
                fieldname: 'comment',
                reqd: 1,
                description: ('Кратко укажите причину отклонения заявки')
            }, 
            (data) => {
                if (data.comment && data.comment.trim()) {
                    addSystemComment(frm, data.comment).then(() => {
                        resolve(true);
                    });
                } else {
                    frappe.msgprint(('Необходимо указать причину Отклонения'));
                    resolve(false);
                }
            }, 
            ('Требуется комментарий'), 
            __('Подтвердить'));
            
            // Настройки размера диалога
            dialog.$wrapper.css({
                'z-index': 99999,
                'width': '400px',
                'max-width': '90%',
                'position': 'fixed', // Устанавливаем фиксированное позиционирование
                'top': '50%', // Сдвигаем вниз на 50% высоты экрана
                'left': '50%', // Сдвигаем вправо на 50% ширины экрана
                'transform': 'translate(-50%, -50%)' // Центрируем по обеим осям
            });
            dialog.$wrapper.find('.modal-dialog').css({
                'z-index': 100000,
                'width': 'auto',
                'margin': '0' // Убираем отступы, так как мы уже центрируем через transform
            });
        }, 100);
    });
}


// Функция добавления системного комментария
function addSystemComment(frm, comment) {
    return frappe.call({
        method: "frappe.desk.form.utils.add_comment",
        args: {
            reference_doctype: frm.doctype,
            reference_name: frm.docname,
            content: comment,
            comment_by: frappe.session.user,
            comment_email: frappe.session.user
        },
        freeze: true
    });
}

// Остальные функции без изменений
async function checkTransitions(frm) {
    const tasks = await frappe.db.get_list("Workflow Task", {
        filters: {
            wt_docname: frm.docname,
            status: "Working",
            doc: frm.doctype,
            state: frm.doc.workflow_state,
            _assign: ["like", `%${frappe.session.user}%`]
        },
        fields: ["name"]
    });

    if (tasks.length === 0) {
        setTimeout(() => frm.page.clear_actions_menu(), 500);
    }
}

async function showDashboard(frm) {
    frm.dashboard.reset();
    if (frm.doc.workflow_state === "На согласовании") {
        const wfTasks = await frappe.db.get_list('Workflow Task', {
            fields: ['_assign'],
            filters: { 
                status: 'Working',
                state: 'На согласовании',
                doc: frm.doctype,
                wt_docname: frm.docname,
                "_assign": ["not like", `%${frm.doc.lauser}%`]
            }
        });

        if (wfTasks.length) {
            let approvers = Array.from( new Set( wfTasks.map((x) => {
                return  frappe.utils.parse_json( x._assign );
                }).flat() ) );
                
            frappe.db.get_list('User', {
                fields: ['full_name'],
                filters: { 
                    name: ["in", approvers ]
                }
            } ).then( function( users ) {
                approvers = users.map( ( user ) => user.full_name );
                frm.dashboard.add_comment( "Ожидается согласование от: " + frappe.utils.comma_and( approvers ), "blue", permanent = true);
            });
        }
    }
