function route( doctype, object ) {
    if ( cur_frm.is_dirty() ) {
        frappe.warn('Вы уверены, что хотите перейти?',
            __('Unsaved timesheet data will be lost!'),
            async () => {
                frappe.set_route('Form', doctype, object);
